// Responsibility: Dynamically mutate game rules by hijacking physics and chaos systems to create a living, unpredictable game state. // Attachment Note: Attach this to an empty GameObject in the scene to act as the master controller of reality shifts. using UnityEngine; using System.Collections.Generic; public class EntropyEngine : MonoBehaviour { private List<GameObject> activeCoins = new List<GameObject>(); private GameObject masterCoin; private void Update() { if (Random.value < 0.001f) TriggerRealityShift(); SyncCoinPhysics(); } public void RegisterCoin(GameObject coin) { activeCoins.Add(coin); masterCoin = coin; } private void SyncCoinPhysics() { if (masterCoin == null || !masterCoin) { activeCoins.RemoveAll(c => c == null); if (activeCoins.Count > 0) masterCoin = activeCoins[0]; return; } Rigidbody masterRb = masterCoin.GetComponent<Rigidbody>(); foreach (var coin in activeCoins) { if (coin != null && coin != masterCoin) { Rigidbody rb = coin.GetComponent<Rigidbody>(); if (rb != null) { rb.velocity = masterRb.velocity; rb.angularVelocity = masterRb.angularVelocity; } } } } public void TriggerRealityShift() { Debug.Log("Reality is fracturing..."); GlobalPhysicsManager.Instance?.SetGravityMultiplier(Random.Range(-2f, 2f)); Time.timeScale = Random.Range(0.5f, 2.0f); ChaosModeManager.Instance?.ApplyRandomForce(); } }